// Test code: the panic-family clippy lints are relaxed by policy
// (assertions and fixture unwraps are the testing idiom); the
// workspace [lints] table holds production code to deny.
#![allow(
    clippy::unwrap_used,
    clippy::expect_used,
    clippy::panic,
    clippy::unreachable,
    clippy::todo,
    clippy::unimplemented
)]

//! Staleness guard for the generated typed CST traversal.
//!
//! `crates/talkbank-parser/src/generated_traversal.rs` is generated by the
//! `tree-sitter-grammar-utils` `generate_typed_traversal` example from this
//! repo's `grammar/src/grammar-contract.json`, the one input the generator
//! reads (see the grammar-change workflow in the book). The wrapper stamps a
//! deterministic provenance header recording the SHA-256 of that file, and
//! of the annotations file when there is one (Chatter has none, and the
//! header says so).
//!
//! This test recomputes the contract digest from the committed file and
//! asserts it matches the digest embedded in the generated file, and that
//! the header states no annotations. If the digest differs, the grammar
//! changed without regenerating the traversal, so the typed traversal (and
//! any consumer built on it) no longer reflects the grammar. The fix is to
//! regenerate, never to hand-edit the generated file.
//!
//! This is the cheap, checkout-free half of the staleness guard: it needs only
//! the committed files, not a checkout of `tree-sitter-grammar-utils`.

use std::fmt::Write as _;
use std::path::PathBuf;

use sha2::{Digest, Sha256};

/// Lowercase hex SHA-256, byte-for-byte matching the wrapper's digest format.
fn sha256_hex(bytes: &[u8]) -> String {
    Sha256::digest(bytes)
        .iter()
        .fold(String::with_capacity(64), |mut acc, byte| {
            // `write!` to a String is infallible; the result is discarded.
            let _ = write!(acc, "{byte:02x}");
            acc
        })
}

/// Repo root, derived from this crate's manifest dir
/// (`<repo>/crates/talkbank-parser-tests`).
fn repo_root() -> PathBuf {
    talkbank_repo::root()
        .expect("runtime chatter checkout")
        .as_path()
        .to_owned()
}

/// The contract digest embedded in the generated file's provenance header.
fn embedded_contract_digest(generated: &str) -> String {
    // One line, shaped:
    //   //! Source grammar digest (sha256): grammar-contract.json=<64hex>
    let re = regex::Regex::new(
        r"(?m)^//! Source grammar digest \(sha256\): grammar-contract\.json=([0-9a-f]{64})$",
    )
    .expect("static digest regex compiles");
    let caps = re.captures(generated).expect(
        "generated_traversal.rs is missing its contract digest line; regenerate it with \
         the grammar-change workflow (the generate_typed_traversal wrapper), never hand-edit \
         the generated file",
    );
    caps[1].to_owned()
}

/// Asserts the committed `generated_traversal.rs` was generated from the
/// current committed contract, with no annotations. A failure means someone
/// changed `grammar.js` and regenerated `grammar/src/` but did not regenerate
/// the typed traversal.
#[test]
fn generated_traversal_is_current() {
    let root = repo_root();
    let contract = std::fs::read(root.join("grammar/src/grammar-contract.json"))
        .expect("grammar/src/grammar-contract.json is readable");

    let generated = std::fs::read_to_string(
        talkbank_repo::root()
            .expect("runtime chatter checkout")
            .join("crates/talkbank-parser/src/generated_traversal.rs"),
    )
    .expect("generated_traversal.rs is readable");

    assert_eq!(
        embedded_contract_digest(&generated),
        sha256_hex(&contract),
        "generated_traversal.rs is STALE: grammar/src/grammar-contract.json changed since it \
         was generated. Regenerate the typed CST traversal (the grammar-change workflow's \
         traversal step) instead of editing the generated file by hand."
    );
    assert!(
        generated
            .lines()
            .any(|line| line == "//! Annotations: none"),
        "generated_traversal.rs does not state that it was generated without annotations; \
         Chatter has no annotations file, so regenerate it with the grammar-change workflow"
    );
}
